/* Phase 4 Lighthouse lab measurements across four portfolio entry points.
 * Reports are generated by CI from real Chromium runs. Never fabricate scores. */
'use strict';
const fs=require('node:fs');
const path=require('node:path');
const root=path.resolve(__dirname,'..');
const out=path.join(root,'quality-artifacts');
fs.mkdirSync(out,{recursive:true});
const pages=[['home','Homepage'],['research','Research'],['projects','Project directory'],['workbench','Engineering Workbench']];
const modes=['mobile','desktop'];
const rows=[];
let missing=0;
const md=[
  '# Site accessibility & performance audit',
  '',
  'Measured Lighthouse *lab* results. These are not field-user Core Web Vitals.',
  'Accessibility scoring is automated and cannot replace manual keyboard, screen-reader, or usability testing.',
  '',
  '| Page | View | Performance | Accessibility | Best practices | SEO | LCP | CLS | TBT |',
  '| --- | --- | ---: | ---: | ---: | ---: | ---: | --- | --- | --- |'
];
function metric(r,key){return r.audits?.[key]?.displayValue||'n/a'}
function score(r,key){const s=r.categories?.[key]?.score;return Number.isFinite(s)?Math.round(s*100):null}
function safe(s){return String(s??'n/a').replace(/[|]/g,'/')}
for(const [slug,label] of pages){
  for(const mode of modes){
    const file=path.join(out,'lighthouse-'+slug+'-'+mode+'.json');
    if(!fs.existsSync(file)){
      console.error('Missing Lighthouse report: '+file);
      missing++;continue;
    }
    let result;
    try{result=JSON.parse(fs.readFileSync(file,'utf8'))}
    catch(error){console.error('Invalid JSON '+file+': '+error.message);missing++;continue}
    if(result.runtimeError){
      console.error('Lighthouse failed for '+label+' '+mode+': '+result.runtimeError.message);
      missing++;continue;
    }
    const scores={performance:score(result,'performance'),accessibility:score(result,'accessibility'),
      bestPractices:score(result,'best-practices'),seo:score(result,'seo')};
    const measures={lcp:metric(result,'largest-contentful-paint'),
      cls:metric(result,'cumulative-layout-shift'),
      tbt:metric(result,'total-blocking-time')};
    rows.push({slug,label,mode,scores,measures,generatedAt:result.fetchTime||null});
    md.push('| '+label+' | '+mode+' | '+safe(scores.performance)+' | '+safe(scores.accessibility)+
      ' | '+safe(scores.bestPractices)+' | '+safe(scores.seo)+' | '+safe(measures.lcp)+
      ' | '+safe(measures.cls)+' | '+safe(measures.tbt)+' |');
  }
}
md.push('','## Interpretation',
  '',
  'Metrics are test-run-dependent. Review raw JSON for each audit and the',
  'Chromium/axe results for actionable WCAG findings.',
  'A lower score does not prove a specific accessibility or performance defect.',
  'The workflow records actual measurements; it does not infer visitor experience.',
  '');
const warnings=[];
for(const entry of rows){
  const {scores,mode,label}=entry;
  const floor=mode==='mobile'?65:80;
  if(scores.performance!==null&&scores.performance<floor)
    warnings.push(label+' ('+mode+'): performance score '+scores.performance+' below review target '+floor);
  if(scores.accessibility!==null&&scores.accessibility<95)
    warnings.push(label+' ('+mode+'): accessibility score '+scores.accessibility+' below review target 95');
  if(scores.seo!==null&&scores.seo<90)
    warnings.push(label+' ('+mode+'): SEO score '+scores.seo+' below review target 90');
}
md.push('## Review targets','','These are attention thresholds, not measured claims or automatic pass/fail gates:',
  'mobile performance 65, desktop performance 80, accessibility 95, SEO 90.','');
if(warnings.length){md.push('### Items needing review','',...warnings.map(s=>'- '+s), '')}
else if(rows.length===pages.length*modes.length){md.push('All Lighthouse review thresholds were met in this lab run.','')}
else{md.push('Some reports are missing; no conclusion can be drawn.','')}
const report=md.join('\n')+'\n';
fs.writeFileSync(path.join(out,'lighthouse-phase4-summary.md'),report);
fs.writeFileSync(path.join(out,'lighthouse-phase4-measurements.json'),JSON.stringify({rows,warnings,missing},null,2));
console.log(report);
if(process.env.GITHUB_STEP_SUMMARY)fs.appendFileSync(process.env.GITHUB_STEP_SUMMARY,report);
if(missing||rows.length!==pages.length*modes.length)process.exitCode=1;
